def zeroOut(data: Any) -> object {
    cols = len(data[0]);
    data = [0 if (col == '') else col for row in data for col in row];
    data = [data[y:(y + cols)] for y in range(0, len(data), cols)];
    return data;
}

"""Returns the center of the given set of 2d coords as a 2-ple."""
def getCenter(coords: Any) -> object {
    xs = [
        c
        for (i, c) in enumerate(coords)
        if ((i % 2) == 0)
    ];
    ys = [
        c
        for (i, c) in enumerate(coords)
        if ((i % 2) == 1)
    ];
    cx = sum(xs) / float(len(xs));
    cy = sum(ys) / float(len(ys));
    return (cx, cy);
}

"""
    Determines whether or not the specified identifier matches
    any of the criteria of the given project context data values
    and returns the result as a boolean.
    """
def is_identifier_match(identifier: str, project: dict) -> bool {
    matches = (
        '{:.0f}'.format((project.get('index', -1) + 1)),
        project.get('uid', ''),
        project.get('name', '')
    );
    return next(
        (
            True
            for m in matches
            if (identifier == m)
        ),
        False
    );
}

"""
    Returns whether the demo should continue to run or not. If demo_mode is
    set to true, the demo should run indefinitely, so the function returns
    true. Otherwise, the function returns true only if step <= max_step
    :param demo_mode: true if running in demo mode
    :param step: current simulation step
    :param max_step: maximum simulation step
    :return: true if the simulation should continue
    """
def running(demo_mode: Any, step: Any, max_step: Any) -> object {
    if demo_mode {
        return True;
    } else {
        return (step <= max_step);
    }
}

"""
    Joins given arguments into an url. Trailing but not leading slashes are
    stripped for each argument.
    """
def urljoin(*args: Any) -> object {
    return "/".join(map(lambda (x: Any) { str(x).rstrip("/"); }, args));
}

